"""Prepare a local project from content generated by the existing Codex Skills."""
import json
from pathlib import Path

from .captions import make_srt, make_timed_srt
from .manifest import project_directory, validate_manifest, write_json
from .visuals import render_ppm
from .tts import dependencies_available, synthesize_scenes, wav_duration


def prepare_project(data, output_root="build/shorts", make_voice=False, speaker=None):
    manifest = validate_manifest(data)
    if make_voice and not dependencies_available():
        raise RuntimeError("Offline Telugu TTS dependencies లేవు; ప్రాజెక్ట్ folder సృష్టించలేదు, auto-install చేయలేదు")
    root = Path(output_root)
    root.mkdir(parents=True, exist_ok=True)
    project = project_directory(root, manifest["project_id"])
    project.mkdir()
    manifest["output_paths"] = {"project_dir": str(project.resolve()),
        "project_manifest": str((project / "project.json").resolve()),
        "script": str((project / "script.txt").resolve()),
        "metadata": str((project / "metadata.json").resolve()),
        "subtitles": str((project / "subtitles.srt").resolve()),
        "narration": str((project / "narration.wav").resolve()),
        "narration_timeline": str((project / "narration-timeline.json").resolve()),
        "hook_scores": str((project / "hook-scores.json").resolve()),
        "scenes": str((project / "scenes").resolve()),
        "preview": str((project / "preview.mp4").resolve())}
    write_json(project / "project.json", manifest)
    write_json(project / "metadata.json", manifest["metadata"])
    write_json(project / "hook-scores.json", manifest["hooks"])
    (project / "script.txt").write_text(manifest["script"] + "\n", encoding="utf-8")
    scene_dir = project / "scenes"
    scene_dir.mkdir()
    for index, scene in enumerate(manifest["scenes"]):
        scene["visual_path"] = f"scenes/{scene['scene_id']}.ppm"
        render_ppm(project / scene["visual_path"], variant=index, prompt=scene["visual_prompt"])
    # Save the final scene list with stable paths.
    write_json(project / "project.json", manifest)
    if make_voice:
        synthesize_scenes(manifest["scenes"], project / "narration.wav",
                          project / "narration-timeline.json", speaker=speaker)
        duration = wav_duration(project / "narration.wav")
        timeline = json.loads((project / "narration-timeline.json").read_text(encoding="utf-8"))
        (project / "subtitles.srt").write_text(make_timed_srt(timeline["segments"], duration), encoding="utf-8")
        state = "ready_for_render"
    else:
        # Approximation is labelled clearly and replaced with exact timing at render time.
        word_count = max(1, len(manifest["script"].split()))
        estimate = max(5.0, word_count / 2.5)
        (project / "subtitles.srt").write_text(make_srt(manifest["script"], estimate), encoding="utf-8")
        state = "needs_local_telugu_voiceover"
    write_json(project / "project.json", manifest)
    write_json(project / "project-status.json", {"status": state,
        "note": "అంచనా subtitle timing; narration WAVతో render సమయంలో తిరిగి సమకాలీకరిస్తాం." if not make_voice else "స్థానిక TTS audio సిద్ధంగా ఉంది."})
    return project


def read_project(project_dir):
    path = Path(project_dir) / "project.json"
    with path.open(encoding="utf-8-sig") as stream:
        return validate_manifest(json.load(stream))
